//! The native API's OpenAPI 3.1 document, generated from its Rust types and served at
//! `GET /v1/syntropy/openapi.json` (RFC-0050 §13; ADR-0503 decision 2; PROD-E4-T02).
//!
//! **Generation.** Every schema in the document comes from a type's `JsonSchema`, generated by
//! `schemars` in JSON Schema 2020-12, the dialect OpenAPI 3.1 uses. Request types are described
//! as they deserialize, response types as they serialize, so an optional response field the
//! server always writes is required in the document. The paths and responses that hold the
//! schemas are written here, one entry per route, since a route is a function and not a type.
//! The document covers the native routes served so far: generate, version and this one.
//!
//! **Streams.** OpenAPI 3.1 has no schema for each item of a stream. A streamed response's media
//! type (`text/event-stream`, `application/x-ndjson`) carries the schema of each event in
//! `x-syntropy-event-schema`: the `data` of each SSE event, and each NDJSON line.
//!
//! **Checking a response.** [`check_response`] checks an HTTP response against the document,
//! each event of a stream on its own. It reads only the JSON Schema keywords the generator
//! writes, and refuses a schema with any other keyword, so a schema it cannot check never
//! passes by being skipped. The integration suites run it over every native response they get.

use std::sync::OnceLock;

use schemars::generate::{Contract, SchemaSettings};
use schemars::{JsonSchema, SchemaGenerator};
use serde_json::{Map, Value, json};

use crate::native::wire::{EventLine, GenerateBody, GenerateResponse};
use crate::routes::ErrorBody;
use crate::version::VersionInfo;

/// The path.
pub const PATH: &str = "/v1/syntropy/openapi.json";

/// Where a document's schemas live, as a JSON pointer.
const SCHEMAS: &str = "/components/schemas";

/// The extension on a streamed media type that holds each event's schema.
pub const EVENT_SCHEMA: &str = "x-syntropy-event-schema";

/// The document, built once.
pub fn document() -> &'static Value {
    static DOCUMENT: OnceLock<Value> = OnceLock::new();
    DOCUMENT.get_or_init(build)
}

fn generator(contract: Contract) -> SchemaGenerator {
    SchemaSettings::draft2020_12()
        .with(|s| {
            s.definitions_path = SCHEMAS.into();
            s.meta_schema = None;
            s.contract = contract;
        })
        .into_generator()
}

/// A reference to `T`'s schema, which `generator` adds to its definitions.
fn schema<T: JsonSchema>(generator: &mut SchemaGenerator) -> Value {
    generator.subschema_for::<T>().to_value()
}

fn build() -> Value {
    let mut requests = generator(Contract::Deserialize);
    let mut responses = generator(Contract::Serialize);
    let generate_body = schema::<GenerateBody>(&mut requests);
    let event = schema::<EventLine>(&mut responses);
    let generate_response = schema::<GenerateResponse>(&mut responses);
    let error = schema::<ErrorBody>(&mut responses);
    let version = schema::<VersionInfo>(&mut responses);

    let mut schemas = requests.take_definitions(true);
    for (name, schema) in responses.take_definitions(true) {
        // No type is both a request and a response type, so no name is in both sets; a type
        // that ever is gets one schema per contract, under two names.
        let name = if schemas.contains_key(&name) {
            format!("{name}Response")
        } else {
            name
        };
        schemas.insert(name, schema);
    }

    let errors = json!({
        "description": "The request failed: the native error (RFC-0050 §12.1).",
        "content": { "application/json": { "schema": error } }
    });
    json!({
        "openapi": "3.1.0",
        "jsonSchemaDialect": "https://json-schema.org/draft/2020-12/schema",
        "info": {
            "title": "Syntropy native API",
            "version": "v1",
            "description": "The native API under /v1/syntropy/ (RFC-0050 §13). Changes within v1 \
                            are additive (ADR-0503 decision 4).",
            "license": { "name": "MIT OR Apache-2.0" }
        },
        "paths": {
            crate::native::PATH: {
                "post": {
                    "operationId": "generate",
                    "summary": "Generate from a prompt, a conversation or token IDs (RFC-0050 §13.1).",
                    "parameters": [{
                        "name": "format",
                        "in": "query",
                        "required": false,
                        "description": "`ndjson` streams one JSON object per line instead of \
                                        Server-Sent Events.",
                        "schema": { "type": "string", "enum": ["ndjson"] }
                    }],
                    "requestBody": {
                        "required": true,
                        "content": { "application/json": { "schema": generate_body } }
                    },
                    "responses": {
                        "200": {
                            "description": "The generation: a stream of events, or one response \
                                            with `stream: false`.",
                            "content": {
                                "text/event-stream": {
                                    "schema": { "type": "string" },
                                    EVENT_SCHEMA: event
                                },
                                "application/x-ndjson": {
                                    "schema": { "type": "string" },
                                    EVENT_SCHEMA: event
                                },
                                "application/json": { "schema": generate_response }
                            }
                        },
                        "default": errors
                    }
                }
            },
            "/v1/syntropy/version": {
                "get": {
                    "operationId": "version",
                    "summary": "The build, the protocol majors and the support tier (RFC-0050 §1.2).",
                    "responses": {
                        "200": {
                            "description": "This node's version.",
                            "content": { "application/json": { "schema": version } }
                        },
                        "default": errors
                    }
                }
            },
            PATH: {
                "get": {
                    "operationId": "openapi",
                    "summary": "This document.",
                    "responses": {
                        "200": {
                            "description": "The OpenAPI 3.1 document.",
                            "content": { "application/json": { "schema": { "type": "object" } } }
                        },
                        "default": errors
                    }
                }
            }
        },
        "components": { "schemas": Value::Object(schemas) }
    })
}

/// Checks a response to `method path` against `doc`: its status's response, or `default`; the
/// media type of `content_type`; and `body`, as one JSON document or, for a stream, each event.
/// A path or method the document does not list must answer 404 or 405 with an `ErrorBody`.
///
/// # Errors
///
/// What does not match, with where.
pub fn check_response(
    doc: &Value,
    method: &str,
    path: &str,
    status: u16,
    content_type: &str,
    body: &[u8],
) -> Result<(), String> {
    let Some(operation) = doc.pointer(&format!("/paths/{}/{method}", escape(path))) else {
        // A route the document does not list exists for no client: the server answers it as a
        // path or method it does not serve, with the native error.
        if !matches!(status, 404 | 405) {
            return Err(format!(
                "the document has no `{method} {path}`, which answered {status}"
            ));
        }
        let error = json!({ "$ref": format!("#{SCHEMAS}/ErrorBody") });
        let body =
            serde_json::from_slice(body).map_err(|e| format!("the body is not JSON: {e}"))?;
        return validate(doc, &error, &body);
    };
    let responses = &operation["responses"];
    let response = responses
        .get(status.to_string())
        .or_else(|| responses.get("default"))
        .ok_or_else(|| format!("`{method} {path}` documents no {status} response"))?;
    let media_type = content_type.split(';').next().unwrap_or("").trim();
    let media = response["content"]
        .get(media_type)
        .ok_or_else(|| format!("`{method} {path}` {status} documents no `{media_type}` body"))?;
    let text = || std::str::from_utf8(body).map_err(|e| format!("the body is not UTF-8: {e}"));
    let parse = |text: &str, at: &str| {
        serde_json::from_str::<Value>(text).map_err(|e| format!("{at} is not JSON: {e}"))
    };
    match media.get(EVENT_SCHEMA) {
        None => validate(doc, &media["schema"], &parse(text()?, "the body")?),
        Some(schema) if media_type == "text/event-stream" => {
            for (n, event) in text()?.split("\n\n").enumerate() {
                check_sse_event(doc, schema, event).map_err(|e| format!("SSE event {n}: {e}"))?;
            }
            Ok(())
        }
        Some(schema) => {
            for (n, line) in text()?.lines().enumerate() {
                let at = format!("NDJSON line {n}");
                validate(doc, schema, &parse(line, &at)?).map_err(|e| format!("{at}: {e}"))?;
            }
            Ok(())
        }
    }
}

/// One SSE event: comment lines are skipped; `data` must match `schema`, and its `id` and
/// `event` must equal the event's `id` and `event` lines.
fn check_sse_event(doc: &Value, schema: &Value, event: &str) -> Result<(), String> {
    let (mut name, mut id, mut data) = (None, None, None);
    for line in event.lines() {
        if line.starts_with(':') {
            continue;
        }
        let (field, value) = line.split_once(": ").unwrap_or((line, ""));
        let slot = match field {
            "event" => &mut name,
            "id" => &mut id,
            "data" => &mut data,
            _ => return Err(format!("unknown line {line:?}")),
        };
        if slot.replace(value).is_some() {
            return Err(format!("`{field}` twice"));
        }
    }
    let Some(data) = data else {
        return match (name, id) {
            (None, None) => Ok(()),
            _ => Err("an event without `data`".to_owned()),
        };
    };
    let value: Value =
        serde_json::from_str(data).map_err(|e| format!("`data` is not JSON: {e}"))?;
    validate(doc, schema, &value)?;
    if name != value["event"].as_str() {
        return Err(format!(
            "`event: {name:?}` but `data.event` is {}",
            value["event"]
        ));
    }
    if id != value["id"].as_str() {
        return Err(format!("`id: {id:?}` but `data.id` is {}", value["id"]));
    }
    Ok(())
}

/// `path` as a JSON pointer token.
fn escape(path: &str) -> String {
    path.replace('~', "~0").replace('/', "~1")
}

/// The keywords [`validate`] reads.
const CHECKED: &[&str] = &[
    "$ref",
    "type",
    "properties",
    "required",
    "additionalProperties",
    "propertyNames",
    "items",
    "enum",
    "const",
    "oneOf",
    "anyOf",
    "allOf",
    "format",
    "minimum",
    "maximum",
    "pattern",
];

/// Keywords that constrain nothing.
const ANNOTATIONS: &[&str] = &["description", "title", "default", "examples", "deprecated"];

/// Checks `value` against `schema`, resolving `$ref`s in `doc`.
///
/// # Errors
///
/// The first mismatch, with its JSON pointer; or a keyword this checker does not read.
pub fn validate(doc: &Value, schema: &Value, value: &Value) -> Result<(), String> {
    check(doc, schema, value, "")
}

fn check(doc: &Value, schema: &Value, value: &Value, at: &str) -> Result<(), String> {
    let schema = match schema {
        Value::Bool(true) => return Ok(()),
        Value::Bool(false) => return Err(format!("{at}: no value is allowed here")),
        Value::Object(schema) => schema,
        _ => return Err(format!("{at}: the schema {schema} is not a schema")),
    };
    for key in schema.keys() {
        if !CHECKED.contains(&key.as_str()) && !ANNOTATIONS.contains(&key.as_str()) {
            return Err(format!("{at}: the checker does not read `{key}`"));
        }
    }
    let fail = |why: String| Err(format!("{at}: {why}, in {value}"));
    if let Some(reference) = schema.get("$ref") {
        let target = reference
            .as_str()
            .and_then(|r| r.strip_prefix('#'))
            .and_then(|pointer| doc.pointer(pointer))
            .ok_or_else(|| format!("{at}: `$ref` {reference} names nothing in the document"))?;
        check(doc, target, value, at)?;
    }
    if let Some(types) = schema.get("type") {
        let names: Vec<&str> = match types {
            Value::String(name) => vec![name],
            Value::Array(names) => names.iter().filter_map(Value::as_str).collect(),
            _ => return fail(format!("`type` {types} is not a type")),
        };
        if !names.iter().any(|name| is_type(value, name)) {
            return fail(format!("not of type {}", names.join(" or ")));
        }
    }
    if let Some(allowed) = schema.get("enum").and_then(Value::as_array)
        && !allowed.contains(value)
    {
        return fail(format!("not one of {}", Value::from(allowed.clone())));
    }
    if let Some(constant) = schema.get("const")
        && constant != value
    {
        return fail(format!("not {constant}"));
    }
    if let Some(format) = schema.get("format").and_then(Value::as_str) {
        check_format(format, value).or_else(fail)?;
    }
    if let (Some(min), Some(n)) = (
        schema.get("minimum").and_then(Value::as_f64),
        value.as_f64(),
    ) && n < min
    {
        return fail(format!("below the minimum {min}"));
    }
    if let (Some(max), Some(n)) = (
        schema.get("maximum").and_then(Value::as_f64),
        value.as_f64(),
    ) && n > max
    {
        return fail(format!("above the maximum {max}"));
    }
    if let (Some(pattern), Some(text)) = (schema.get("pattern"), value.as_str()) {
        check_pattern(pattern, text).or_else(fail)?;
    }
    if let Some(object) = value.as_object() {
        check_object(doc, schema, object, at)?;
    }
    if let (Some(items), Some(array)) = (schema.get("items"), value.as_array()) {
        for (i, item) in array.iter().enumerate() {
            check(doc, items, item, &format!("{at}/{i}"))?;
        }
    }
    if let Some(all) = schema.get("allOf").and_then(Value::as_array) {
        for sub in all {
            check(doc, sub, value, at)?;
        }
    }
    if let Some(any) = schema.get("anyOf").and_then(Value::as_array)
        && !any.iter().any(|sub| check(doc, sub, value, at).is_ok())
    {
        return fail("matches none of `anyOf`".to_owned());
    }
    if let Some(one) = schema.get("oneOf").and_then(Value::as_array) {
        let matched = one
            .iter()
            .filter(|sub| check(doc, sub, value, at).is_ok())
            .count();
        if matched != 1 {
            return fail(format!("matches {matched} of `oneOf`, not exactly one"));
        }
    }
    Ok(())
}

fn check_object(
    doc: &Value,
    schema: &Map<String, Value>,
    object: &Map<String, Value>,
    at: &str,
) -> Result<(), String> {
    let properties = schema.get("properties").and_then(Value::as_object);
    if let Some(required) = schema.get("required").and_then(Value::as_array) {
        for name in required.iter().filter_map(Value::as_str) {
            if !object.contains_key(name) {
                return Err(format!("{at}: `{name}` is required"));
            }
        }
    }
    for (name, field) in object {
        let here = format!("{at}/{}", name.replace('~', "~0").replace('/', "~1"));
        if let Some(names) = schema.get("propertyNames") {
            check(doc, names, &Value::String(name.clone()), &here)?;
        }
        match properties.and_then(|p| p.get(name)) {
            Some(sub) => check(doc, sub, field, &here)?,
            None => {
                if let Some(extra) = schema.get("additionalProperties") {
                    check(doc, extra, field, &here)?;
                }
            }
        }
    }
    Ok(())
}

fn is_type(value: &Value, name: &str) -> bool {
    match name {
        "null" => value.is_null(),
        "boolean" => value.is_boolean(),
        "object" => value.is_object(),
        "array" => value.is_array(),
        "string" => value.is_string(),
        "number" => value.is_number(),
        "integer" => value.is_i64() || value.is_u64(),
        _ => false,
    }
}

/// The formats the generator writes: integer widths, and the floating-point ones, which add
/// nothing to `type: number`.
fn check_format(format: &str, value: &Value) -> Result<(), String> {
    if !value.is_number() {
        return Ok(());
    }
    let (min, max): (i128, i128) = match format {
        "float" | "double" => return Ok(()),
        "uint8" => (0, u8::MAX.into()),
        "uint16" => (0, u16::MAX.into()),
        "uint32" => (0, u32::MAX.into()),
        "uint64" | "uint" => (0, u64::MAX.into()),
        "int8" => (i8::MIN.into(), i8::MAX.into()),
        "int16" => (i16::MIN.into(), i16::MAX.into()),
        "int32" => (i32::MIN.into(), i32::MAX.into()),
        "int64" | "int" => (i64::MIN.into(), i64::MAX.into()),
        other => return Err(format!("the checker does not read the format `{other}`")),
    };
    let n = value
        .as_u64()
        .map(i128::from)
        .or_else(|| value.as_i64().map(i128::from))
        .ok_or_else(|| format!("not an integer for `{format}`"))?;
    if (min..=max).contains(&n) {
        Ok(())
    } else {
        Err(format!("outside `{format}`"))
    }
}

fn check_pattern(pattern: &Value, text: &str) -> Result<(), String> {
    let pattern = pattern
        .as_str()
        .ok_or_else(|| format!("`pattern` {pattern} is not a string"))?;
    let regex =
        regex::Regex::new(pattern).map_err(|e| format!("`pattern` {pattern:?} is invalid: {e}"))?;
    if regex.is_match(text) {
        Ok(())
    } else {
        Err(format!("does not match {pattern:?}"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn walk<'a>(value: &'a Value, out: &mut Vec<&'a Value>) {
        match value {
            Value::Object(map) => {
                out.push(value);
                map.values().for_each(|v| walk(v, out));
            }
            Value::Array(items) => items.iter().for_each(|v| walk(v, out)),
            _ => {}
        }
    }

    #[test]
    fn the_document_is_openapi_3_1_and_every_ref_resolves() {
        let doc = document();
        assert_eq!(doc["openapi"], "3.1.0");
        let schemas = doc["components"]["schemas"].as_object().unwrap();
        for name in [
            "GenerateBody",
            "Message",
            "CacheControl",
            "Sampling",
            "LogitBias",
            "EventLine",
            "GenerateResponse",
            "ErrorBody",
            "VersionInfo",
        ] {
            assert!(schemas.contains_key(name), "{name}: {:?}", schemas.keys());
        }
        let mut objects = Vec::new();
        walk(doc, &mut objects);
        let refs: Vec<&str> = objects
            .iter()
            .filter_map(|o| o.get("$ref").and_then(Value::as_str))
            .collect();
        assert!(!refs.is_empty());
        for r in refs {
            assert!(
                doc.pointer(r.strip_prefix('#').unwrap()).is_some(),
                "{r} resolves"
            );
        }
    }

    /// The keywords of `schema` and of every schema inside it that the checker does not read.
    fn unread(schema: &Value, at: &str, out: &mut Vec<String>) {
        let Value::Object(map) = schema else { return };
        for (key, sub) in map {
            let here = format!("{at}/{key}");
            match key.as_str() {
                "properties" => {
                    for (name, field) in sub.as_object().into_iter().flatten() {
                        unread(field, &format!("{here}/{name}"), out);
                    }
                }
                "items" | "additionalProperties" | "propertyNames" => unread(sub, &here, out),
                "oneOf" | "anyOf" | "allOf" => {
                    for (i, s) in sub.as_array().into_iter().flatten().enumerate() {
                        unread(s, &format!("{here}/{i}"), out);
                    }
                }
                k if CHECKED.contains(&k) || ANNOTATIONS.contains(&k) => {}
                _ => out.push(here),
            }
        }
    }

    /// Every schema in the document uses only keywords the checker reads, so no part of a
    /// response escapes the check.
    #[test]
    fn the_checker_reads_every_keyword_the_document_uses() {
        let doc = document();
        let mut out = Vec::new();
        for (name, schema) in doc["components"]["schemas"].as_object().unwrap() {
            unread(schema, name, &mut out);
        }
        assert_eq!(out, Vec::<String>::new());
    }

    #[test]
    fn the_request_schema_refuses_what_the_parser_refuses() {
        let doc = document();
        let body = json!({ "$ref": "#/components/schemas/GenerateBody" });
        let good = json!({
            "model": "m",
            "messages": [{ "role": "user", "content": [{ "type": "text", "text": "hi",
                           "cache_control": { "type": "ephemeral", "ttl": "1h" } }] }],
            "sampling": { "logit_bias": { "7": 1.5 }, "stop_token_ids": [3], "max_tokens": 4 },
            "raw_special_tokens": true
        });
        validate(doc, &body, &good).unwrap();
        for bad in [
            json!({ "model": "m", "tokens": [1], "bogus": 1 }),
            json!({ "model": "m", "tokens": [-1] }),
            json!({ "model": "m", "tokens": [4_294_967_296_u64] }),
            json!({ "model": "m", "sampling": { "logit_bias": { "01": 1 } } }),
            json!({ "model": "m", "stream_coalesce_ms": 201 }),
            json!({ "tokens": [1] }),
            json!({ "model": "m", "messages": [{ "role": "user", "content": "x",
                    "cache_control": { "type": "persistent" } }] }),
        ] {
            assert!(validate(doc, &body, &bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn streams_are_checked_event_by_event() {
        let doc = document();
        let line =
            |id: &str, event: &str| format!(r#"{{"id":"{id}","event":"{event}","text":"hi"}}"#);
        let ndjson = format!("{}\n{}\n", line("s:0", "text"), line("s:1", "text"));
        check_response(
            doc,
            "post",
            crate::native::PATH,
            200,
            "application/x-ndjson",
            ndjson.as_bytes(),
        )
        .unwrap();
        let sse = format!(
            "event: text\nid: s:0\ndata: {}\n\n: keepalive\n\n",
            line("s:0", "text")
        );
        check_response(
            doc,
            "post",
            crate::native::PATH,
            200,
            "text/event-stream",
            sse.as_bytes(),
        )
        .unwrap();
        let mismatched = format!("event: text\nid: s:1\ndata: {}\n\n", line("s:0", "text"));
        assert!(
            check_response(
                doc,
                "post",
                crate::native::PATH,
                200,
                "text/event-stream",
                mismatched.as_bytes()
            )
            .is_err()
        );
        let unknown = format!("{}\n", line("s:0", "texts"));
        assert!(
            check_response(
                doc,
                "post",
                crate::native::PATH,
                200,
                "application/x-ndjson",
                unknown.as_bytes()
            )
            .is_err()
        );
        let error =
            br#"{"error":{"class":"InvalidRequest","code":"invalid_request","message":"m"}}"#;
        check_response(
            doc,
            "post",
            crate::native::PATH,
            400,
            "application/json",
            error,
        )
        .unwrap();
        let bad_class = br#"{"error":{"class":"Nope","code":"x","message":"m"}}"#;
        assert!(
            check_response(
                doc,
                "post",
                crate::native::PATH,
                400,
                "application/json",
                bad_class
            )
            .is_err()
        );
    }
}
